"""Derived scan-sequence constants for the of135i driver -- IR-enabled
(alternating visible/IR line) scan mode.

AUTO-GENERATED by driver/gen_tables.py's main_ir() from
traces/04-singel-3600-IRpa.trace.json.gz -- do not edit by hand.
Regenerate with: .venv/bin/python driver/gen_tables.py

Structures the IR-enabled 3600 dpi single-frame scan flow (see
../cal-data/ir/ir-analysis.md and gen_tables.py's main_ir() for the
full phase-boundary derivation) the same way of135i/tables.py
structures the plain visible-only trace: an ordered list of PHASES,
each holding its FULL verbatim op stream (control writes/reads,
coalesced status polls, bulk-OUT and bulk-IN, in captured order
with captured dt pacing) for its trace op-index range, replayed by
device.py's executor exactly as tables.py's phases are. Two
differences from tables.py: every calibration buffer here is at
the raw sensor width (5184 px, alternating IR/visible lines) and
the shading table uploads to TWO addresses instead of one --
see Phase.injections' shading_table_visible/shading_table_ir
(and shading_table2_visible/shading_table2_ir).
"""

from __future__ import annotations

from dataclasses import dataclass, field, replace


@dataclass(frozen=True)
class Op:
    """One verbatim operation from the captured trace, in order.

    See of135i/tables.py's Op for the full field-by-field
    description (kind/dt/bm/br/wv/wi/data/length/resp/dur) --
    identical shape here, just sourced from trace 04 instead of 03.
    """

    kind: str
    dt: float = 0.0
    bm: int = 0
    br: int = 0
    wv: int = 0
    wi: int = 0
    data: bytes = b""
    length: int = 0
    resp: bytes = b""
    dur: float = 0.0


@dataclass
class Phase:
    """One named step of the IR scan sequence -- see of135i/tables.py's
    Phase for the full description of ops/injections/split_at and
    patched(). Injection specs and patched() semantics are identical;
    only the *names* available differ per phase (see main_ir()'s
    docstring in gen_tables.py -- most notably the shading-table
    injections come in visible/IR pairs here instead of a single name).
    """

    name: str
    op_range: tuple[int, int]   # trace op-index range this phase covers (provenance)
    ops: list[Op] = field(default_factory=list)
    injections: dict[str, tuple] = field(default_factory=dict)
    split_at: int | None = None

    def patched(self, **values: bytes) -> list[Op]:
        """Return a copy of ops with named injection points
        overwritten by the given values -- see of135i/tables.py's
        Phase.patched() for the full semantics."""
        out = list(self.ops)
        for name, val in values.items():
            spec = self.injections.get(name)
            if spec is None:
                continue
            if spec[0] == "byte":
                _, idx, off = spec
                data = bytearray(out[idx].data)
                data[off:off + len(val)] = val
                out[idx] = replace(out[idx], data=bytes(data))
            elif spec[0] == "bo":
                _, idxs = spec
                total = sum(len(out[idx].data) for idx in idxs)
                if len(val) > total:
                    raise ValueError(
                        f"injection {name!r}: got {len(val)} B, "
                        f"expected at most {total} B"
                    )
                padded = bytes(val) + bytes(total - len(val))
                pos = 0
                for idx in idxs:
                    n = len(out[idx].data)
                    out[idx] = replace(out[idx], data=padded[pos:pos + n])
                    pos += n
        return out


