# --------------------------------------------------------------------- FEEDL
# FEEDL = target absolute position, counted in 1/7200 inch (HWDPI), from
# home -- same convention as tables.py. FEEDL_FRAME1_IR is this trace's
# own captured frame-1 value; FEEDL_PITCH_IR is NOT independently observed
# here (a single-frame capture) and is carried over from tables.FEEDL_PITCH
# as a documented assumption -- open question for hardware validation
# once a multi-frame IR-mode capture exists.
FEEDL_FRAME1 = 6746
FEEDL_PITCH = 10760


def feedl_for_frame(frame: int) -> int:
    """Absolute FEEDL target for `frame` (1-based), from home."""
    return FEEDL_FRAME1 + (frame - 1) * FEEDL_PITCH

